{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Bumetanide, a structurally related sulfamoyl anthranilic acid loop diuretic, has absolute oral bioavailability of 80% in normal subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Hydrochlorothiazide, a chlorinated sulfonamide diuretic sharing the sulfamoyl benzene motif, has absolute oral bioavailability of 66-75%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tolfenamic acid, an anthranilic acid NSAID with a carboxylic acid and halogenated aromatic rings, has absolute oral bioavailability of 60.4%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Meclofenamate, a fenamate with a carboxylic acid and chlorinated rings, has oral bioavailability above 85%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Metolazone, a sulfonamide diuretic, is available in an approximately 100% bioavailable form.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Para-aminosalicylic acid, a small polar aminobenzoic acid, has oral bioavailability of 50-60%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Azosemide, a close furosemide analog, has low oral bioavailability of 10-19% in humans, indicating that some analogs in this class can fall below 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "The closest-scoring record reports low F (15%) for furosemide acyl glucuronide, a much more polar conjugate; this is not a direct measure of furosemide parent bioavailability and has limited transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is furosemide. Multiple structurally related loop diuretics and sulfonamide/anthranilic acid drugs (bumetanide, hydrochlorothiazide, tolfenamic acid, meclofenamate, metolazone, PAS) show oral bioavailability well above 20%, often 60-100%. The closest direct analog with the same sulfamoyl anthranilic acid core, bumetanide, has absolute F ~66-96%. Azosemide, a more distant analog, has lower F (~10-20%), but furosemide itself is known to have higher F; the low azosemide values are borderline and may reflect specific absorption/efflux differences. The physicochemical prior predicts low due to ionization/polarity, but experimental evidence from close analogs overrides it. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability value for furosemide itself was provided; closest evidence is from analogs and a glucuronide metabolite.",
    "Azosemide data are conflicting (10% vs 20.4%) and may not fully represent furosemide.",
    "Physicochemical prior suggests low permeability, but experimental analog data override."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

